def _split_key_value(line: str) -> tuple[str, str] | None:
    """Split ``line`` at its first ``=`` or ``:``."""
    equals = line.find("=")
    colon = line.find(":")
    if equals == -1 and colon == -1:
        return None
    if equals == -1:
        position = colon
    elif colon == -1:
        position = equals
    else:
        position = min(equals, colon)
    key = line[:position].strip().lower()
    value = line[position + 1 :].strip()
    return key, value


def _interpolate(sections: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    """Interpolate every value, returning a new nested dict."""
    memo: dict[tuple[str, str], str] = {}
    visiting: list[tuple[str, str]] = []
    visiting_set: set[tuple[str, str]] = set()

    def resolve(section: str, key: str) -> str:
        node = (section, key)
        if node in memo:
            return memo[node]
        if node in visiting_set:
            chain = " -> ".join(f"{sec}:{name}" for sec, name in visiting + [node])
            raise InterpolationError(f"circular reference: {chain}")

        visiting.append(node)
        visiting_set.add(node)
        template = sections[section][key]
        parts: list[str] = []
        index = 0
        length = len(template)

        while index < length:
            char = template[index]
            if char != "$":
                parts.append(char)
                index += 1
                continue
            if index + 1 < length and template[index + 1] == "$":
                parts.append("$")
                index += 2
                continue
            if index + 1 < length and template[index + 1] == "{":
                end = template.find("}", index + 2)
                if end != -1:
                    reference = template[index + 2 : end]
                    parts.append(_resolve_reference(reference, section))
                    index = end + 1
                    continue
            # A lone `$`, `$x`, or an unclosed `${...` stays unchanged.
            parts.append("$")
            index += 1

        visiting.pop()
        visiting_set.remove(node)
        result = "".join(parts)
        memo[node] = result
        return result

    def _resolve_reference(reference: str, section: str) -> str:
        reference_section, separator, reference_key = reference.partition(":")
        if separator:
            reference_section = reference_section.strip()
            target_section = reference_section
        else:
            reference_key = reference_section
            target_section = section
        target_key = reference_key.strip().lower()

        if target_section not in sections:
            raise InterpolationError(
                f"reference to missing section {target_section!r} in ${{{reference}}}"
            )
        if target_key not in sections[target_section]:
            raise InterpolationError(
                f"reference to missing key {target_key!r} "
                f"in section {target_section!r}"
            )
        return resolve(target_section, target_key)

    return {
        section: {key: resolve(section, key) for key in keys}
        for section, keys in sections.items()
    }


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    continuation_section: str | None = None
    continuation_key: str | None = None

    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped[0] in "#;":
            # Blank lines and comments end any continuation.
            continuation_section = None
            continuation_key = None
            continue

        if line[0].isspace() and continuation_key is not None:
            sections[continuation_section][continuation_key] += "\n" + stripped
            continue

        # Anything else ends the current continuation and is parsed normally.
        continuation_section = None
        continuation_key = None

        if stripped.startswith("["):
            if not stripped.endswith("]"):
                raise ParseError(lineno, f"malformed section header {stripped!r}")
            name = stripped[1:-1].strip()
            sections.setdefault(name, {})
            current_section = name
            continue

        split = _split_key_value(stripped)
        if split is None:
            raise ParseError(
                lineno,
                f"expected a section header or a key/value line, got {stripped!r}",
            )
        key, value = split
        if not key:
            raise ParseError(lineno, "empty key")
        if current_section is None:
            raise ParseError(lineno, "key before any section")

        sections[current_section][key] = value
        continuation_section = current_section
        continuation_key = key

    return _interpolate(sections)

